import VertexSource, { generateVertexGlsl } from './vertex-source.js'
import { computeSkinningMatrices, applySkinning } from './geometry.js'

// Blend mode configurations for regl
const BLEND_MODES = {
  normal: {
    enable: true,
    func: {
      srcRGB: 'src alpha',
      srcAlpha: 1,
      dstRGB: 'one minus src alpha',
      dstAlpha: 'one minus src alpha'
    }
  },
  add: {
    enable: true,
    func: {
      srcRGB: 'src alpha',
      srcAlpha: 1,
      dstRGB: 'one',
      dstAlpha: 'one'
    }
  },
  multiply: {
    enable: true,
    func: {
      srcRGB: 'dst color',
      srcAlpha: 1,
      dstRGB: 'zero',
      dstAlpha: 'one'
    }
  },
  screen: {
    enable: true,
    func: {
      srcRGB: 'one',
      srcAlpha: 1,
      dstRGB: 'one minus src color',
      dstAlpha: 'one'
    }
  }
}

var Output = function ({ regl, precision, label = "", chanNum, hydraSynth, width, height}) {
  this.regl = regl
  this.precision = precision
  this.label = label
  this.chanNum = chanNum
  this.hydraSynth = hydraSynth

  // Default fullscreen triangle (covers clip space with overdraw)
  // Using vec3 for forward compatibility with 3D (z=0 for 2D)
  this.defaultPositionBuffer = this.regl.buffer([
    [-2, 0, 0],
    [0, -2, 0],
    [2, 2, 0]
  ])
  // Keep for backwards compatibility
  this.positionBuffer = this.defaultPositionBuffer

  // Sprite registry: Map<spriteLevel, SpriteConfig>
  this.sprites = new Map()

  this.draw = () => {}
  this.init()
  this.pingPongIndex = 0

  // for each output, create two fbos for pingponging
  // Depth buffer added lazily when 3D geometry is first used
  this.hasDepthBuffer = false
  this.fbos = (Array(2)).fill().map(() => this.regl.framebuffer({
    color: this.regl.texture({
      mag: 'nearest',
      width: width,
      height: height,
      format: 'rgba'
    }),
    depthStencil: false
  }))

  // array containing render passes
//  this.passes = []
}

Output.prototype.resize = function(width, height) {
  // Guard against invalid dimensions
  if (!width || !height || width <= 0 || height <= 0) {
    console.warn(`[Output] resize called with invalid dimensions: ${width}x${height}`)
    return
  }
  this.fbos.forEach((fbo) => {
    fbo.resize(width, height)
  })
//  console.log(this)
}

// Lazily enable depth buffer for 3D rendering
// Called automatically when 3D geometry is first registered
Output.prototype.enableDepthBuffer = function() {
  if (this.hasDepthBuffer) return  // Already enabled

  // Get current dimensions from existing fbo
  const width = this.fbos[0].width
  const height = this.fbos[0].height

  // Destroy old framebuffers
  this.fbos.forEach(fbo => fbo.destroy())

  // Create new framebuffers with depth
  this.fbos = (Array(2)).fill().map(() => this.regl.framebuffer({
    color: this.regl.texture({
      mag: 'nearest',
      width: width,
      height: height,
      format: 'rgba'
    }),
    depth: true
  }))

  this.hasDepthBuffer = true
}

Output.prototype.getCurrent = function () {
  return this.fbos[this.pingPongIndex]
}

Output.prototype.getTexture = function () {
   var index = this.pingPongIndex ? 0 : 1
  return this.fbos[index]
}

Output.prototype.init = function () {
//  console.log('clearing')
  this.transformIndex = 0
  this.fragHeader = `
  precision ${this.precision} float;

  uniform float time;
  varying vec2 uv;
  `

  this.fragBody = ``

  // Vertex shader uses vec3 for forward compatibility with 3D
  this.vert = `
  precision ${this.precision} float;
  attribute vec3 position;
  varying vec2 uv;
  varying float v_faceId;
  varying float v_instanceId;

  // Vertex data for fragment shader (default values for fullscreen quad)
  varying vec3 v_position;
  varying vec3 v_normal;
  varying vec3 v_worldNormal;
  varying vec3 v_tangent;
  varying vec3 v_bitangent;
  varying vec3 v_viewDir;
  varying float v_depth;

  void main () {
    uv = position.xy;
    v_faceId = 0.0;
    v_instanceId = 0.0;

    // Default vertex data for fullscreen quad
    v_position = vec3(position.xy * 2.0 - 1.0, 0.0);
    v_normal = vec3(0.0, 0.0, 1.0);
    v_worldNormal = vec3(0.0, 0.0, 1.0);
    v_tangent = vec3(1.0, 0.0, 0.0);
    v_bitangent = vec3(0.0, 1.0, 0.0);
    v_viewDir = vec3(0.0, 0.0, 1.0);
    v_depth = 1.0;

    gl_Position = vec4(2.0 * position.xy - 1.0, 0, 1);
  }`

  this.attributes = {
    position: this.positionBuffer
  }
  this.uniforms = {
    time: this.regl.prop('time'),
    resolution: this.regl.prop('resolution')
  }

  this.frag = `
       ${this.fragHeader}

      void main () {
        vec4 c = vec4(0, 0, 0, 0);
        vec2 st = uv;
        ${this.fragBody}
        gl_FragColor = c;
      }
  `

  // Create copy command for persistence (no level 0 = keep previous frame)
  this.copyCommand = this.regl({
    frag: `
      precision ${this.precision} float;
      uniform sampler2D source;
      varying vec2 uv;
      void main () {
        gl_FragColor = texture2D(source, uv);
      }
    `,
    vert: this.vert,
    attributes: {
      position: this.defaultPositionBuffer
    },
    uniforms: {
      source: this.regl.prop('source')
    },
    count: 3,
    depth: { enable: false }
  })

  return this
}


// Reshape vertex data to vec3 format for forward compatibility with 3D
// Input: flat array of 2D coords [x,y, x,y, ...] or 3D coords [x,y,z, x,y,z, ...]
// Output: array of [x,y,z] triples
// is3D: explicit flag indicating 3D data (required for ambiguous lengths like 108 which is divisible by both 2 and 3)
function reshapeToVec3(flatArray, is3D = false) {
  const len = flatArray.length
  const stride = is3D ? 3 : 2

  const verts = []
  for (let i = 0; i < len; i += stride) {
    if (is3D) {
      verts.push([flatArray[i], flatArray[i + 1], flatArray[i + 2]])
    } else {
      // 2D input: add z=0
      verts.push([flatArray[i], flatArray[i + 1], 0.0])
    }
  }
  return verts
}

// Helper to normalize vertex option values (handles scalars, arrays, and lambdas)
function normalizeVertexOption(value, defaultValue) {
  if (value === undefined || value === null) return defaultValue
  return value
}

// Register a sprite at a given level
// spriteLevel 0 clears the buffer before drawing
// spriteLevel 1+ composites over previous content
Output.prototype.registerSprite = function (spriteLevel, config) {
  const { passes, vertexData, blendMode = 'normal', vertexOptions = null, primitive = 'triangles', sprite = null, enabled = true } = config
  const pass = passes[0]
  const self = this

  // Extract raw vertices and check for VertexSource
  let rawVerts = null
  let vertexSource = null
  let has3D = false

  if (vertexData instanceof VertexSource) {
    vertexSource = vertexData
    rawVerts = vertexData.vertices
    has3D = vertexData.is3D || false
  } else if (vertexData && Array.isArray(vertexData)) {
    rawVerts = vertexData
  }

  // Enable depth buffer lazily for 3D geometry
  if (has3D) {
    this.enableDepthBuffer()
  }

  // Create vertex buffer for this sprite
  let positionBuffer, uvBuffer, faceIdBuffer, normalBuffer, tangentBuffer, colorBuffer, vertexCount
  let bounds = { minX: -1, maxX: 1, minY: -1, maxY: 1 }  // default fullscreen bounds
  let hasExplicitUVs = false
  let hasFaceIds = false
  let hasNormals = false
  let hasTangents = false
  let hasColors = false

  if (rawVerts && rawVerts.length >= 6) {
    // Custom geometry: reshape to vec3 for 3D forward-compatibility
    const verts = reshapeToVec3(rawVerts, has3D)
    positionBuffer = this.regl.buffer(verts)
    vertexCount = verts.length


    // Check for explicit UVs from VertexSource (e.g., cube)
    if (vertexSource && vertexSource.uvs && vertexSource.uvs.length > 0) {
      hasExplicitUVs = true
      // Reshape UVs to vec2 array
      const uvData = []
      for (let i = 0; i < vertexSource.uvs.length; i += 2) {
        uvData.push([vertexSource.uvs[i], vertexSource.uvs[i + 1]])
      }
      uvBuffer = this.regl.buffer(uvData)
    } else {
      // Compute bounds for UV normalization
      bounds = { minX: Infinity, maxX: -Infinity, minY: Infinity, maxY: -Infinity }
      for (const v of verts) {
        bounds.minX = Math.min(bounds.minX, v[0])
        bounds.maxX = Math.max(bounds.maxX, v[0])
        bounds.minY = Math.min(bounds.minY, v[1])
        bounds.maxY = Math.max(bounds.maxY, v[1])
      }
    }

    // Check for face IDs from VertexSource (e.g., cube for per-face materials)
    if (vertexSource && vertexSource.faceIds && vertexSource.faceIds.length > 0) {
      hasFaceIds = true
      // Wrap each faceId in array for explicit per-vertex scalar format
      // This matches how position [[x,y,z],...] and texcoord [[u,v],...] are structured
      faceIdBuffer = this.regl.buffer(vertexSource.faceIds.map(id => [id]))
    }

    // Check for normals from VertexSource (e.g., from GLB/OBJ models)
    if (vertexSource && vertexSource.normals && vertexSource.normals.length > 0) {
      hasNormals = true
      // Reshape normals to vec3 array
      const normalData = []
      for (let i = 0; i < vertexSource.normals.length; i += 3) {
        normalData.push([vertexSource.normals[i], vertexSource.normals[i + 1], vertexSource.normals[i + 2]])
      }
      normalBuffer = this.regl.buffer(normalData)
    }

    // Check for tangents from VertexSource (vec4: xyz = tangent, w = handedness)
    if (vertexSource && vertexSource.tangents && vertexSource.tangents.length > 0) {
      hasTangents = true
      // Reshape tangents to vec4 array
      const tangentData = []
      for (let i = 0; i < vertexSource.tangents.length; i += 4) {
        tangentData.push([vertexSource.tangents[i], vertexSource.tangents[i + 1], vertexSource.tangents[i + 2], vertexSource.tangents[i + 3]])
      }
      tangentBuffer = this.regl.buffer(tangentData)
    }

    // Check for vertex colors from VertexSource (vec4: RGBA)
    if (vertexSource && vertexSource.colors && vertexSource.colors.length > 0) {
      hasColors = true
      // Reshape colors to vec4 array
      const colorData = []
      for (let i = 0; i < vertexSource.colors.length; i += 4) {
        colorData.push([vertexSource.colors[i], vertexSource.colors[i + 1], vertexSource.colors[i + 2], vertexSource.colors[i + 3]])
      }
      colorBuffer = this.regl.buffer(colorData)
    }
  }

  // Check for fragment data from VertexSource (for explosion effects)
  let hasFragments = false
  let fragmentCenterBuffer = null
  let fragmentSeedBuffer = null
  let fragmentDistanceBuffer = null

  if (vertexSource && vertexSource.isFragmentized) {
    hasFragments = true

    // Fragment centers (vec3 per vertex)
    if (vertexSource.fragmentCenters && vertexSource.fragmentCenters.length > 0) {
      const centerData = []
      for (let i = 0; i < vertexSource.fragmentCenters.length; i += 3) {
        centerData.push([
          vertexSource.fragmentCenters[i],
          vertexSource.fragmentCenters[i + 1],
          vertexSource.fragmentCenters[i + 2]
        ])
      }
      fragmentCenterBuffer = this.regl.buffer(centerData)
    }

    // Fragment seeds (float per vertex)
    if (vertexSource.fragmentSeeds && vertexSource.fragmentSeeds.length > 0) {
      fragmentSeedBuffer = this.regl.buffer(Array.from(vertexSource.fragmentSeeds).map(s => [s]))
    }

    // Fragment distances (float per vertex)
    if (vertexSource.fragmentDistances && vertexSource.fragmentDistances.length > 0) {
      fragmentDistanceBuffer = this.regl.buffer(Array.from(vertexSource.fragmentDistances).map(d => [d]))
    }
  }

  // Check for GPU instancing data from VertexSource
  let hasInstancing = false
  let hasCpuInstancing = false  // CPU fallback when GPU instancing not available
  let instanceCount = 0
  let instanceOffsetBuffer = null
  let instanceIdBuffer = null
  let instanceRotationBuffer = null
  let instanceScaleBuffer = null

  // Check if regl supports GPU instancing
  const supportsInstancing = this.regl.hasExtension('ANGLE_instanced_arrays')

  if (vertexSource && vertexSource.instancePositions && vertexSource.instanceCount > 0) {
    const baseVertCount = vertexSource.vertices ? vertexSource.vertices.length / 3 : 0
    instanceCount = vertexSource.instanceCount

    if (supportsInstancing) {
      // GPU instancing path
      hasInstancing = true

      // Log instance setup info
      const totalVerts = baseVertCount * instanceCount
      console.log(`[hydra-vertex] GPU Instancing: ${instanceCount} instances × ${baseVertCount} vertices = ${totalVerts} total vertices`)

      // Reshape instance positions to vec3 array
      const offsetData = []
      for (let i = 0; i < vertexSource.instancePositions.length; i += 3) {
        offsetData.push([
          vertexSource.instancePositions[i],
          vertexSource.instancePositions[i + 1],
          vertexSource.instancePositions[i + 2]
        ])
      }
      instanceOffsetBuffer = this.regl.buffer(offsetData)

      // Create instance ID buffer (gl_InstanceID not available in WebGL 1)
      // Each instance gets its index: [0, 1, 2, 3, ...]
      const idData = []
      for (let i = 0; i < instanceCount; i++) {
        idData.push([i])
      }
      instanceIdBuffer = this.regl.buffer(idData)

      // Create instance rotation buffer if provided (vec3 euler angles)
      if (vertexSource.instanceRotations) {
        const rotData = []
        for (let i = 0; i < vertexSource.instanceRotations.length; i += 3) {
          rotData.push([
            vertexSource.instanceRotations[i],
            vertexSource.instanceRotations[i + 1],
            vertexSource.instanceRotations[i + 2]
          ])
        }
        instanceRotationBuffer = this.regl.buffer(rotData)
      }

      // Create instance scale buffer if provided (vec3)
      if (vertexSource.instanceScales) {
        const scaleData = []
        for (let i = 0; i < vertexSource.instanceScales.length; i += 3) {
          scaleData.push([
            vertexSource.instanceScales[i],
            vertexSource.instanceScales[i + 1],
            vertexSource.instanceScales[i + 2]
          ])
        }
        instanceScaleBuffer = this.regl.buffer(scaleData)
      }
    } else {
      // CPU fallback: duplicate vertices with offsets baked in
      console.log(`[hydra-vertex] CPU Instancing fallback: ${instanceCount} instances × ${baseVertCount} vertices = ${baseVertCount * instanceCount} total vertices`)

      const origVerts = vertexSource.vertices
      const origUvs = vertexSource.uvs
      const origNormals = vertexSource.normals
      const origFaceIds = vertexSource.faceIds
      const positions = vertexSource.instancePositions

      // Expand vertices: duplicate N times, apply offsets
      const expandedVerts = new Float32Array(origVerts.length * instanceCount)
      for (let inst = 0; inst < instanceCount; inst++) {
        const ox = positions[inst * 3]
        const oy = positions[inst * 3 + 1]
        const oz = positions[inst * 3 + 2]
        for (let v = 0; v < origVerts.length; v += 3) {
          const idx = inst * origVerts.length + v
          expandedVerts[idx] = origVerts[v] + ox
          expandedVerts[idx + 1] = origVerts[v + 1] + oy
          expandedVerts[idx + 2] = origVerts[v + 2] + oz
        }
      }

      // Expand UVs: just duplicate N times
      let expandedUvs = null
      if (origUvs && origUvs.length > 0) {
        expandedUvs = new Float32Array(origUvs.length * instanceCount)
        for (let inst = 0; inst < instanceCount; inst++) {
          expandedUvs.set(origUvs, inst * origUvs.length)
        }
      }

      // Expand normals: just duplicate N times
      let expandedNormals = null
      if (origNormals && origNormals.length > 0) {
        expandedNormals = new Float32Array(origNormals.length * instanceCount)
        for (let inst = 0; inst < instanceCount; inst++) {
          expandedNormals.set(origNormals, inst * origNormals.length)
        }
      }

      // Expand faceIds: just duplicate N times
      let expandedFaceIds = null
      if (origFaceIds && origFaceIds.length > 0) {
        expandedFaceIds = new Float32Array(origFaceIds.length * instanceCount)
        for (let inst = 0; inst < instanceCount; inst++) {
          expandedFaceIds.set(origFaceIds, inst * origFaceIds.length)
        }
      }

      // Create per-vertex instance ID so _ix works
      // Each vertex knows which instance it belongs to
      const expandedInstanceIds = new Float32Array(baseVertCount * instanceCount)
      for (let inst = 0; inst < instanceCount; inst++) {
        for (let v = 0; v < baseVertCount; v++) {
          expandedInstanceIds[inst * baseVertCount + v] = inst
        }
      }

      // Update the vertexSource with expanded data
      vertexSource.vertices = expandedVerts
      if (expandedUvs) vertexSource.uvs = expandedUvs
      if (expandedNormals) vertexSource.normals = expandedNormals
      if (expandedFaceIds) vertexSource.faceIds = expandedFaceIds

      // Store the per-vertex instance IDs for the shader
      vertexSource._cpuInstanceIds = expandedInstanceIds

      // Clear GPU instancing data - we've baked it into vertices
      vertexSource.instancePositions = null
      vertexSource.instanceCount = 0

      // Update rawVerts to the expanded version
      rawVerts = expandedVerts

      // Recreate position buffer with expanded vertices
      const verts = reshapeToVec3(rawVerts, has3D)
      positionBuffer = this.regl.buffer(verts)
      vertexCount = verts.length

      // Recreate UV buffer if present
      if (expandedUvs) {
        hasExplicitUVs = true
        const uvData = []
        for (let i = 0; i < expandedUvs.length; i += 2) {
          uvData.push([expandedUvs[i], expandedUvs[i + 1]])
        }
        uvBuffer = this.regl.buffer(uvData)
      }

      // Recreate normal buffer if present
      if (expandedNormals) {
        hasNormals = true
        const normalData = []
        for (let i = 0; i < expandedNormals.length; i += 3) {
          normalData.push([expandedNormals[i], expandedNormals[i + 1], expandedNormals[i + 2]])
        }
        normalBuffer = this.regl.buffer(normalData)
      }

      // Recreate faceId buffer if present
      if (expandedFaceIds) {
        hasFaceIds = true
        faceIdBuffer = this.regl.buffer(expandedFaceIds.map(id => [id]))
      }

      // Create per-vertex instanceId buffer (no divisor - regular per-vertex attribute)
      instanceIdBuffer = this.regl.buffer(expandedInstanceIds.map(id => [id]))

      // Mark that we're using CPU instancing (for shader generation)
      hasCpuInstancing = true

      // Reset instanceCount since we're not using GPU instancing
      instanceCount = 0
    }
  }

  if (!rawVerts) {
    // Default fullscreen triangle
    positionBuffer = this.defaultPositionBuffer
    vertexCount = 3
  }

  // Check if we need vertex transforms (from vertexOptions OR VertexSource chain)
  const hasChainedTransforms = vertexSource && vertexSource.hasTransforms
  const hasVertexOptions = rawVerts && vertexOptions && (
    vertexOptions.scale !== undefined ||
    vertexOptions.offset !== undefined ||
    vertexOptions.rotation !== undefined
  )
  const hasVertexTransforms = hasChainedTransforms || hasVertexOptions

  // Build uniforms with prevBuffer and resolution (for aspect ratio correction)
  const uniforms = Object.assign({}, pass.uniforms, {
    prevBuffer: () => self.fbos[self.pingPongIndex],
    resolution: this.regl.prop('resolution')
  })

  // Add sprite UV uniform (default = full texture)
  if (sprite && sprite.getUVBounds) {
    // Dynamic sprite picker - call getUVBounds each frame
    uniforms.u_spriteUV = () => {
      const bounds = sprite.getUVBounds()
      return [bounds.uMin, bounds.vMin, bounds.uMax, bounds.vMax]
    }
  } else {
    // No sprite picking - use full texture
    uniforms.u_spriteUV = [0, 0, 1, 1]
  }

  // Add sprite grid uniform for faceId-based picking
  // If sprite has grid info, use it; otherwise default to [1, 1] (single cell)
  if (sprite && sprite.cols && sprite.rows) {
    uniforms.u_spriteGrid = [sprite.cols, sprite.rows]
  } else {
    uniforms.u_spriteGrid = [1, 1]
  }

  // Add facesPerInstance uniform for unique sprites per instance
  // Combines instanceId * facesPerInstance + faceId for sprite picking
  if (sprite && sprite.facesPerInstance) {
    uniforms.u_facesPerInstance = sprite.facesPerInstance
  } else {
    uniforms.u_facesPerInstance = 0  // Disabled by default
  }

  // Add bounds uniforms for UV normalization (custom geometry only)
  if (rawVerts) {
    uniforms.u_boundsMin = [bounds.minX, bounds.minY]
    uniforms.u_boundsMax = [bounds.maxX, bounds.maxY]
  }

  // Add vertex transform uniforms if needed (Phase 3 style only)
  // Phase 5 chained transforms get uniforms from generateVertexGlsl
  if (hasVertexOptions) {
    // Scale: can be number, [x,y] array, or lambda
    const scaleOpt = normalizeVertexOption(vertexOptions.scale, [1, 1])
    uniforms.u_scale = (context, props) => {
      const val = typeof scaleOpt === 'function' ? scaleOpt() : scaleOpt
      if (typeof val === 'number') return [val, val]
      return val
    }

    // Offset: can be [x,y] array or lambda
    const offsetOpt = normalizeVertexOption(vertexOptions.offset, [0, 0])
    uniforms.u_offset = (context, props) => {
      const val = typeof offsetOpt === 'function' ? offsetOpt() : offsetOpt
      return val
    }

    // Rotation: can be number (radians) or lambda
    const rotationOpt = normalizeVertexOption(vertexOptions.rotation, 0)
    uniforms.u_rotation = (context, props) => {
      const val = typeof rotationOpt === 'function' ? rotationOpt() : rotationOpt
      return val
    }
  }

  // Create vertex shader based on whether we have custom geometry
  let vert
  let vertexUniforms = {}

  if (rawVerts) {
    if (hasChainedTransforms) {
      // Use generateVertexGlsl for chained transforms (Phase 5)
      const generated = generateVertexGlsl(vertexSource, this.precision, {
        useExplicitUVs: hasExplicitUVs,
        useFaceIds: hasFaceIds,
        useNormals: hasNormals,
        useTangents: hasTangents,
        useColors: hasColors,
        useInstancing: hasInstancing,
        useCpuInstancing: hasCpuInstancing,
        useInstanceRotation: hasInstancing && !!instanceRotationBuffer,
        useInstanceScale: hasInstancing && !!instanceScaleBuffer,
        useFragments: hasFragments
      })
      vert = generated.glsl
      vertexUniforms = generated.uniforms
    } else if (hasVertexOptions) {
      // Custom geometry with vertexOptions (Phase 3 style)
      const uvAttrDecl = hasExplicitUVs ? 'attribute vec2 texcoord;' : ''
      const faceIdAttrDecl = hasFaceIds ? 'attribute float faceId;' : ''
      const uvCode = hasExplicitUVs
        ? 'uv = texcoord;'
        : 'uv = (position.xy - u_boundsMin) / (u_boundsMax - u_boundsMin);'
      const faceIdCode = hasFaceIds ? 'v_faceId = faceId;' : 'v_faceId = 0.0;'

      // Instancing support for Phase 3 style
      // GPU instancing: needs instanceOffset and instanceId with divisor
      // CPU instancing: only needs instanceId (per-vertex, offsets baked into vertices)
      const instanceAttrDecl = hasInstancing
        ? `attribute vec3 instanceOffset;
      attribute float instanceId;`
        : (hasCpuInstancing ? 'attribute float instanceId;' : '')
      const instanceIdPassthrough = (hasInstancing || hasCpuInstancing) ? 'v_instanceId = instanceId;' : 'v_instanceId = 0.0;'
      const instanceOffsetCode = hasInstancing ? 'pos += instanceOffset.xy;' : ''

      vert = `
      precision ${this.precision} float;
      attribute vec3 position;
      ${instanceAttrDecl}
      ${uvAttrDecl}
      ${faceIdAttrDecl}
      varying vec2 uv;
      varying float v_faceId;
      varying float v_instanceId;

      // Vertex data for fragment shader
      varying vec3 v_position;
      varying vec3 v_normal;
      varying vec3 v_viewDir;
      varying float v_depth;

      uniform vec2 u_scale;
      uniform vec2 u_offset;
      uniform float u_rotation;
      uniform vec2 u_boundsMin;
      uniform vec2 u_boundsMax;

      void main () {
        // UV ${hasExplicitUVs ? 'from explicit attribute' : 'normalized to shape bounds'}
        ${uvCode}
        ${faceIdCode}
        ${instanceIdPassthrough}

        // Apply transforms
        vec2 pos = position.xy * u_scale;

        // Rotation around origin
        float c = cos(u_rotation);
        float s = sin(u_rotation);
        pos = vec2(pos.x * c - pos.y * s, pos.x * s + pos.y * c);

        // Offset (uniform offset + instance offset)
        pos += u_offset;
        ${instanceOffsetCode}

        // Default vertex data for 2D geometry
        v_position = vec3(pos, 0.0);
        v_normal = vec3(0.0, 0.0, 1.0);
        v_viewDir = vec3(0.0, 0.0, 1.0);
        v_depth = 1.0;

        gl_Position = vec4(pos, 0.0, 1.0);
        gl_PointSize = 2.0;
      }`
    } else {
      // Custom geometry without transforms: simple passthrough
      const uvAttrDecl = hasExplicitUVs ? 'attribute vec2 texcoord;' : ''
      const faceIdAttrDecl = hasFaceIds ? 'attribute float faceId;' : ''
      const normalAttrDecl = hasNormals ? 'attribute vec3 normal;' : ''
      const uvCode = hasExplicitUVs
        ? 'uv = texcoord;'
        : 'uv = (position.xy - u_boundsMin) / (u_boundsMax - u_boundsMin);'
      const faceIdCode = hasFaceIds ? 'v_faceId = faceId;' : 'v_faceId = 0.0;'
      const normalCode = hasNormals ? 'v_normal = normalize(normal);' : 'v_normal = vec3(0.0, 0.0, 1.0);'

      // Instancing support for passthrough mode
      // GPU instancing: needs instanceOffset and instanceId with divisor
      // CPU instancing: only needs instanceId (per-vertex, offsets baked into vertices)
      const instanceAttrDecl = hasInstancing
        ? `attribute vec3 instanceOffset;
      attribute float instanceId;`
        : (hasCpuInstancing ? 'attribute float instanceId;' : '')
      const instanceIdPassthrough = (hasInstancing || hasCpuInstancing) ? 'v_instanceId = instanceId;' : 'v_instanceId = 0.0;'
      const instanceOffsetCode = hasInstancing ? 'pos += instanceOffset;' : ''

      // Position transform depends on whether we have instancing (need mutable pos) or not
      const positionCode = has3D
        ? (hasInstancing ? 'vec3 pos = position;' : 'v_position = position;')
        : (hasInstancing ? 'vec3 pos = position;' : 'v_position = vec3(position.xy, 0.0);')
      const finalPositionCode = hasInstancing ? 'v_position = pos;' : ''

      const glPositionCode = has3D
        ? (hasInstancing
          ? `float aspect = resolution.x / resolution.y;
        gl_Position = vec4(pos.x / aspect, pos.y, pos.z * 0.1, 1.0);`
          : `float aspect = resolution.x / resolution.y;
        gl_Position = vec4(position.x / aspect, position.y, position.z * 0.1, 1.0);`)
        : (hasInstancing
          ? 'gl_Position = vec4(pos.xy, 0.0, 1.0);'
          : 'gl_Position = vec4(position.xy, 0.0, 1.0);')

      vert = `
      precision ${this.precision} float;
      attribute vec3 position;
      ${instanceAttrDecl}
      ${uvAttrDecl}
      ${faceIdAttrDecl}
      ${normalAttrDecl}
      varying vec2 uv;
      varying float v_faceId;
      varying float v_instanceId;

      // Vertex data for fragment shader
      varying vec3 v_position;
      varying vec3 v_normal;
      varying vec3 v_worldNormal;
      varying vec3 v_viewDir;
      varying float v_depth;

      uniform vec2 u_boundsMin;
      uniform vec2 u_boundsMax;
      uniform vec2 resolution;

      void main () {
        // UV ${hasExplicitUVs ? 'from explicit attribute' : 'normalized to shape bounds'}
        ${uvCode}
        ${faceIdCode}
        ${instanceIdPassthrough}

        // Position with optional instancing offset
        ${positionCode}
        ${instanceOffsetCode}
        ${finalPositionCode}

        // Vertex data
        ${normalCode}
        v_worldNormal = v_normal;
        v_viewDir = vec3(0.0, 0.0, 1.0);
        v_depth = 1.0;

        ${glPositionCode}
        gl_PointSize = 2.0;
      }`
    }
  } else {
    // Fullscreen: use original vertex shader
    vert = this.vert
  }

  // Merge vertex uniforms with fragment uniforms
  Object.assign(uniforms, vertexUniforms)

  // Build attributes object
  const attributes = {
    position: positionBuffer
  }
  if (hasExplicitUVs && uvBuffer) {
    attributes.texcoord = uvBuffer
  }
  if (hasFaceIds && faceIdBuffer) {
    attributes.faceId = faceIdBuffer
  }
  if (hasNormals && normalBuffer) {
    attributes.normal = normalBuffer
  }
  if (hasTangents && tangentBuffer) {
    attributes.tangent = tangentBuffer
  }
  if (hasColors && colorBuffer) {
    attributes.color = colorBuffer
  }
  // Add fragment attributes for explosion effects (per-vertex, no divisor)
  if (hasFragments) {
    if (fragmentCenterBuffer) {
      attributes.fragmentCenter = fragmentCenterBuffer
    }
    if (fragmentSeedBuffer) {
      attributes.fragmentSeed = fragmentSeedBuffer
    }
    if (fragmentDistanceBuffer) {
      attributes.fragmentDistance = fragmentDistanceBuffer
    }
  }
  // Add instance attributes with divisor=1 (advances once per instance)
  if (hasInstancing && instanceOffsetBuffer) {
    attributes.instanceOffset = {
      buffer: instanceOffsetBuffer,
      divisor: 1
    }
    // Instance ID attribute (WebGL 1 doesn't have gl_InstanceID)
    attributes.instanceId = {
      buffer: instanceIdBuffer,
      divisor: 1
    }
    // Per-instance rotation (euler angles xyz)
    if (instanceRotationBuffer) {
      attributes.instanceRotation = {
        buffer: instanceRotationBuffer,
        divisor: 1
      }
    }
    // Per-instance scale (xyz)
    if (instanceScaleBuffer) {
      attributes.instanceScale = {
        buffer: instanceScaleBuffer,
        divisor: 1
      }
    }
  }

  // CPU instancing: instanceId as regular per-vertex attribute (no divisor)
  if (hasCpuInstancing && instanceIdBuffer) {
    attributes.instanceId = instanceIdBuffer
  }

  // Create the draw command
  const drawConfig = {
    frag: pass.frag,
    vert: vert,
    attributes: attributes,
    uniforms: uniforms,
    count: vertexCount,
    primitive: primitive,
    blend: BLEND_MODES[blendMode] || BLEND_MODES.normal,
    depth: { enable: has3D, func: 'less' }
  }

  // Add instancing if enabled
  if (hasInstancing) {
    drawConfig.instances = instanceCount
    // Warn about very high instance counts
    if (instanceCount > 5000) {
      console.warn(`[hydra-vertex] ⚠️ High instance count: ${instanceCount}. This may cause GPU performance issues.`)
    }
  }

  // Wrap shader compilation in try-catch to provide helpful errors
  let drawCommand
  try {
    drawCommand = this.regl(drawConfig)
  } catch (err) {
    console.error('[hydra-vertex] ❌ Shader compilation failed!')
    console.error('[hydra-vertex] Error:', err.message)

    // Try to extract line info from error
    if (err.message.includes('ERROR:')) {
      console.error('[hydra-vertex] This is usually caused by invalid shader expressions or unsupported GLSL operations.')
    }

    // Log shader sources for debugging (truncated)
    console.group('[hydra-vertex] Shader sources (for debugging):')
    console.log('Vertex shader (first 500 chars):', vert.substring(0, 500) + '...')
    console.log('Fragment shader (first 500 chars):', pass.frag.substring(0, 500) + '...')
    console.groupEnd()

    // Return early - sprite won't render but won't crash
    return
  }

  // Store sprite config with all buffer references for cleanup
  const spriteConfig = {
    drawCommand,
    positionBuffer,
    uvBuffer,
    faceIdBuffer,
    normalBuffer,
    tangentBuffer,
    colorBuffer,
    fragmentCenterBuffer,
    fragmentSeedBuffer,
    fragmentDistanceBuffer,
    instanceOffsetBuffer,
    instanceIdBuffer,
    instanceRotationBuffer,
    instanceScaleBuffer,
    blendMode,
    has3D,
    hasInstancing,
    hasFragments,
    instanceCount,
    enabled
  }

  // Store animation data if present
  if (vertexSource && vertexSource._animTimeFunc) {
    spriteConfig.animation = {
      skeleton: vertexSource._skeleton,
      animations: vertexSource._animations,
      clipName: vertexSource._animClip,
      timeFunc: vertexSource._animTimeFunc,
      originalVerts: vertexSource._originalVerts || vertexSource.vertices,
      originalNormals: vertexSource._originalNormals || vertexSource.normals,
      joints: vertexSource.joints,
      weights: vertexSource.weights,
      gltf: vertexSource._gltf,
      normCenter: vertexSource._normCenter,  // For denormalize/renormalize during skinning
      normScale: vertexSource._normScale,
      is3D: has3D
    }
  }

  this.sprites.set(spriteLevel, spriteConfig)
}

// Clear all sprites (called by hush)
Output.prototype.clearSprites = function () {
  // Clean up all GPU buffers for each sprite
  for (const [level, sprite] of this.sprites) {
    if (sprite.positionBuffer && sprite.positionBuffer !== this.defaultPositionBuffer) {
      sprite.positionBuffer.destroy()
    }
    if (sprite.uvBuffer) {
      sprite.uvBuffer.destroy()
    }
    if (sprite.faceIdBuffer) {
      sprite.faceIdBuffer.destroy()
    }
    if (sprite.normalBuffer) {
      sprite.normalBuffer.destroy()
    }
    if (sprite.tangentBuffer) {
      sprite.tangentBuffer.destroy()
    }
    if (sprite.colorBuffer) {
      sprite.colorBuffer.destroy()
    }
    if (sprite.fragmentCenterBuffer) {
      sprite.fragmentCenterBuffer.destroy()
    }
    if (sprite.fragmentSeedBuffer) {
      sprite.fragmentSeedBuffer.destroy()
    }
    if (sprite.fragmentDistanceBuffer) {
      sprite.fragmentDistanceBuffer.destroy()
    }
    if (sprite.instanceOffsetBuffer) {
      sprite.instanceOffsetBuffer.destroy()
    }
    if (sprite.instanceIdBuffer) {
      sprite.instanceIdBuffer.destroy()
    }
    if (sprite.instanceRotationBuffer) {
      sprite.instanceRotationBuffer.destroy()
    }
    if (sprite.instanceScaleBuffer) {
      sprite.instanceScaleBuffer.destroy()
    }
  }
  this.sprites.clear()
}

// Remove a specific sprite level
Output.prototype.removeSprite = function (level) {
  if (this.sprites.has(level)) {
    const sprite = this.sprites.get(level)
    // Clean up all GPU buffers
    if (sprite.positionBuffer && sprite.positionBuffer !== this.defaultPositionBuffer) {
      sprite.positionBuffer.destroy()
    }
    if (sprite.uvBuffer) {
      sprite.uvBuffer.destroy()
    }
    if (sprite.faceIdBuffer) {
      sprite.faceIdBuffer.destroy()
    }
    if (sprite.normalBuffer) {
      sprite.normalBuffer.destroy()
    }
    if (sprite.tangentBuffer) {
      sprite.tangentBuffer.destroy()
    }
    if (sprite.colorBuffer) {
      sprite.colorBuffer.destroy()
    }
    if (sprite.fragmentCenterBuffer) {
      sprite.fragmentCenterBuffer.destroy()
    }
    if (sprite.fragmentSeedBuffer) {
      sprite.fragmentSeedBuffer.destroy()
    }
    if (sprite.fragmentDistanceBuffer) {
      sprite.fragmentDistanceBuffer.destroy()
    }
    if (sprite.instanceOffsetBuffer) {
      sprite.instanceOffsetBuffer.destroy()
    }
    if (sprite.instanceIdBuffer) {
      sprite.instanceIdBuffer.destroy()
    }
    if (sprite.instanceRotationBuffer) {
      sprite.instanceRotationBuffer.destroy()
    }
    if (sprite.instanceScaleBuffer) {
      sprite.instanceScaleBuffer.destroy()
    }
    this.sprites.delete(level)
  }
}

// Enable/disable a sprite level (keeps it registered but skips rendering)
Output.prototype.enableSprite = function (level, enabled = true) {
  if (this.sprites.has(level)) {
    this.sprites.get(level).enabled = enabled
  }
}

Output.prototype.disableSprite = function (level) {
  this.enableSprite(level, false)
}

// Legacy render method - registers at sprite level 0
Output.prototype.render = function (passes) {
  // Clear existing sprite at level 0 and register new one
  if (this.sprites.has(0)) {
    const oldSprite = this.sprites.get(0)
    // Clean up all GPU buffers from old sprite
    if (oldSprite.positionBuffer && oldSprite.positionBuffer !== this.defaultPositionBuffer) {
      oldSprite.positionBuffer.destroy()
    }
    if (oldSprite.uvBuffer) {
      oldSprite.uvBuffer.destroy()
    }
    if (oldSprite.faceIdBuffer) {
      oldSprite.faceIdBuffer.destroy()
    }
    if (oldSprite.normalBuffer) {
      oldSprite.normalBuffer.destroy()
    }
    if (oldSprite.tangentBuffer) {
      oldSprite.tangentBuffer.destroy()
    }
    if (oldSprite.colorBuffer) {
      oldSprite.colorBuffer.destroy()
    }
    if (oldSprite.fragmentCenterBuffer) {
      oldSprite.fragmentCenterBuffer.destroy()
    }
    if (oldSprite.fragmentSeedBuffer) {
      oldSprite.fragmentSeedBuffer.destroy()
    }
    if (oldSprite.fragmentDistanceBuffer) {
      oldSprite.fragmentDistanceBuffer.destroy()
    }
    if (oldSprite.instanceOffsetBuffer) {
      oldSprite.instanceOffsetBuffer.destroy()
    }
    if (oldSprite.instanceIdBuffer) {
      oldSprite.instanceIdBuffer.destroy()
    }
    if (oldSprite.instanceRotationBuffer) {
      oldSprite.instanceRotationBuffer.destroy()
    }
    if (oldSprite.instanceScaleBuffer) {
      oldSprite.instanceScaleBuffer.destroy()
    }
  }
  this.registerSprite(0, { passes, vertexData: null, blendMode: 'normal' })

  // For backwards compatibility, also set this.draw
  const self = this
  this.draw = function(props) {
    self._renderSprites(props)
  }
}

// Internal method to render all sprites in order
Output.prototype._renderSprites = function (props) {
  if (this.sprites.size === 0) {
    // No sprites - clear framebuffer (for hush())
    this.pingPongIndex = this.pingPongIndex ? 0 : 1
    const targetFbo = this.fbos[this.pingPongIndex]
    this.regl.clear({
      color: [0, 0, 0, 1],
      depth: 1,
      framebuffer: targetFbo
    })
    return
  }

  // Sort sprite levels ascending
  const levels = Array.from(this.sprites.keys()).sort((a, b) => a - b)

  // Swap ping-pong index once at start of frame
  this.pingPongIndex = this.pingPongIndex ? 0 : 1
  const targetFbo = this.fbos[this.pingPongIndex]
  const prevFbo = this.fbos[this.pingPongIndex ? 0 : 1]

  // Check if we have an enabled level 0 (which clears)
  const level0Sprite = this.sprites.get(0)
  const hasLevel0 = levels.includes(0) && level0Sprite && level0Sprite.enabled !== false

  // Check if any sprite uses 3D (needs depth clearing)
  const needs3D = Array.from(this.sprites.values()).some(s => s.has3D)

  // If no level 0, copy previous frame for persistence/trails
  // If level 0 exists, clear to start fresh
  if (!hasLevel0) {
    this.regl.clear({
      color: [0, 0, 0, 0],
      depth: needs3D ? 1 : undefined,
      framebuffer: targetFbo
    })
    if (this.copyCommand) {
      targetFbo.use(() => {
        this.copyCommand({ source: prevFbo })
      })
    }
  } else {
    // Level 0 clears the framebuffer
    this.regl.clear({
      color: [0, 0, 0, 1],
      depth: needs3D ? 1 : undefined,
      framebuffer: targetFbo
    })
  }

  // Render each sprite level
  for (let i = 0; i < levels.length; i++) {
    const level = levels[i]
    const sprite = this.sprites.get(level)

    // Skip disabled sprites
    if (sprite.enabled === false) continue

    // Update animation buffers if this sprite is animated
    if (sprite.animation) {
      const anim = sprite.animation
      const time = typeof anim.timeFunc === 'function' ? anim.timeFunc() : 0

      // Support dynamic clip name (function or string)
      const clipName = typeof anim.clipName === 'function' ? anim.clipName() : anim.clipName

      // Find clip and compute looped time (don't loop here - let timeFunc handle it for dynamic clips)
      const clip = anim.animations.find(a => a.name === clipName) || anim.animations[0]
      const loopedTime = clip ? (time % clip.duration) : time

      // Compute skinning matrices (pre-transformed for normalized coordinate space)
      const skinningMatrices = computeSkinningMatrices(
        anim.skeleton, anim.animations, clipName, loopedTime, anim.gltf,
        anim.normCenter, anim.normScale
      )

      if (skinningMatrices) {
        // Apply skinning to vertices
        const skinned = applySkinning(
          anim.originalVerts, anim.originalNormals,
          anim.joints, anim.weights, skinningMatrices
        )

        // Update position buffer with skinned vertices
        const skinnedVec3 = []
        for (let j = 0; j < skinned.vertices.length; j += 3) {
          skinnedVec3.push([skinned.vertices[j], skinned.vertices[j + 1], skinned.vertices[j + 2]])
        }
        sprite.positionBuffer(skinnedVec3)

        // Update normal buffer if present
        if (sprite.normalBuffer && skinned.normals) {
          const skinnedNormals = []
          for (let j = 0; j < skinned.normals.length; j += 3) {
            skinnedNormals.push([skinned.normals[j], skinned.normals[j + 1], skinned.normals[j + 2]])
          }
          sprite.normalBuffer(skinnedNormals)
        }
      }
    }

    // Draw to framebuffer
    targetFbo.use(() => {
      sprite.drawCommand(props)
    })
  }
}

Output.prototype.tick = function (props) {
  this._renderSprites(props)
}

export default Output
